from pathlib import Path
import json, shutil, html, os

ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'dist'
BASE=os.environ.get('SITE_URL','https://myjerry243.github.io/daimeng-website').rstrip('/')
# GitHub Pages project sites are served from /<repo>/, so root-absolute links need that prefix.
# Set SITE_PREFIX='' when the site is published at a domain root (or behind a custom domain).
PREFIX=os.environ.get('SITE_PREFIX','/daimeng-website').strip('/')
PREFIX='/'+PREFIX if PREFIX else ''
PAGES=[]
def esc(s): return html.escape(str(s),quote=True)
def brand(): return '<a class="brand" href="/" aria-label="Daimeng Technology home"><span class="brand-symbol" aria-hidden="true"></span><span class="brand-name">DAIMENG<small>ALUMINIUM ENGINEERING</small></span></a>'
def btn(text,href,kind=''): return f'<a class="btn {kind}" href="{href}">{text}</a>'
def link(text,href): return f'<a class="text-link" href="{href}">{text}</a>'
def image(name,alt,lazy=True): return f'<img src="/assets/{name}.webp" alt="{esc(alt)}" loading="{"lazy" if lazy else "eager"}" width="1600" height="1000">'
def cta(): return '<section class="cta"><div class="wrap"><div><span class="eyebrow">LET’S BUILD YOUR NEXT LINE</span><h2>Better production begins<br>with the right conversation.</h2><p>Share your profile, capacity and finishing requirements.</p></div>'+btn('Discuss your project','/contact/','dark')+'</div></section>'
def faq(items): return '<div class="faq">'+''.join(f'<details><summary>{esc(q)}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
def page(path,title,desc,body,faqs=None,noindex=False):
    nav=[('Solutions','/solutions/'),('Projects','/projects/'),('Engineering insights','/insights/'),('About us','/about/')]
    navhtml=''.join(f'<a href="{u}"'+(' aria-current="page"' if path==u else '')+f'>{t}</a>' for t,u in nav)
    schema=[{'@context':'https://schema.org','@type':'Organization','name':'Foshan Diamond Technology Co., Ltd.','alternateName':'Daimeng Technology','url':BASE,'email':'DM_tech@yeah.net','telephone':'+86-186-7610-8902'}]
    if path!='/': schema.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title.split('|')[0].strip(),'item':BASE+path}]})
    if faqs: schema.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faqs]})
