GUIDES=[('Planning / 6 min','Vertical or horizontal?<br>Start with your production mix.','A practical framework for comparing line layouts before you commit to a specification.','/insights/vertical-vs-horizontal/'),('Project preparation / 5 min','What makes a useful<br>anodizing line brief?','The information your engineering team needs to turn an idea into a meaningful proposal.','/insights/anodizing-line-planning/'),('Automation / 4 min','Connect your line.<br>Understand your production.','Plan the information exchange between your control system and factory management software.','/insights/mes-integration/')]
def guides(): return '<div class="grid-3">'+''.join(f'<article class="guide-card"><small>{cat}</small><h3><a href="{u}">{t}</a></h3><p>{d}</p>{link("Read the guide",u)}</article>' for cat,t,d,u in GUIDES)+'</div>'

home='''<section class="hero"><img class="hero-photo" src="/assets/hero.webp" alt="Daimeng aluminium anodizing production line inside a factory" width="1920" height="1080" fetchpriority="high"><div class="wrap hero-content"><span class="eyebrow">ALUMINIUM SURFACE TREATMENT SOLUTIONS</span><h1>Engineered for<br>your next <em>level<br>of production.</em></h1><p>Automatic anodizing lines. Intelligent control.<br>One integrated approach to aluminium finishing.</p><div class="actions">'''+btn('Explore our solutions','/solutions/')+btn('Find the right line','/line-selector/','light-outline')+'''</div><div class="hero-bottom"><span><b>FROM PROCESS TO PRODUCTION</b>Design &nbsp; / &nbsp; Equipment &nbsp; / &nbsp; Automation</span><span>BUILT AROUND YOUR PROFILE.<br>CONNECTED TO YOUR FACTORY.</span></div></div></section><div class="strip"><div class="wrap"><div class="strip-item"><b>Vertical & horizontal</b><small>Purpose-built line configurations</small></div><div class="strip-item"><b>Process to control</b><small>Integrated production systems</small></div><div class="strip-item"><b>MES / ERP ready</b><small>Connect your production data</small></div><div class="strip-item"><b>Made for your project</b><small>Engineering from Foshan, China</small></div></div></div><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">OUR SOLUTIONS</span><h2>The right line.<br>A stronger operation.</h2></div><p>Start with what you manufacture.<br>We’ll help you define how to finish it.</p></div>'''+cards()+'''</div></section><section class="section dark"><div class="wrap split"><div><span class="eyebrow">INTELLIGENCE IN EVERY STAGE</span><h2>Your process.<br>Working as one.</h2><p>Coordinate handling, process recipes and production data. Make the line easier to operate and the information easier to use.</p><ul class="feature-list"><li><span>01</span> Recipe-driven, coordinated equipment control</li><li><span>02</span> Fixed and flexible production modes</li><li><span>03</span> Production reporting and MES / ERP interfaces</li></ul>'''+btn('Discover our control system','/automation/','light-outline')+'''</div>'''+image('control','Daimeng central control system interface')+'''</div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">PROJECT SPOTLIGHT</span><h2>Engineering in practice.</h2></div>'''+link('Explore our references','/projects/')+'''</div><article class="project-feature">'''+image('vertical','Daimeng vertical anodizing equipment; illustrative equipment image, not a project-site photograph')+'''<div class="project-copy"><span class="eyebrow">MALAYSIA / VERTICAL ANODIZING</span><h3>Press Metal PV<br>(SARAWAK) SDN. BHD</h3><p>A fully automatic vertical anodizing line featured in Daimeng’s published project references.</p><p class="image-reference">Equipment image shown for illustration.</p><div class="tags"><span class="tag">Aluminium profiles</span><span class="tag">Automatic handling</span></div>'''+link('View project','/projects/press-metal/')+'''</div></article></div></section><section class="section muted"><div class="wrap"><span class="eyebrow">A CLEAR PATH FORWARD</span><h2>From your first brief<br>to a defined solution.</h2><div class="process"><div><strong>01 / DISCOVER</strong><h3>Your production</h3><p>Profiles, finishes, capacity and business priorities.</p></div><div><strong>02 / DEFINE</strong><h3>The process</h3><p>Agree the treatment route and automation scope.</p></div><div><strong>03 / PLAN</strong><h3>The line</h3><p>Review the layout, utilities and equipment interfaces.</p></div><div><strong>04 / ALIGN</strong><h3>The project</h3><p>Define supply, installation and commissioning responsibilities.</p></div><div><strong>05 / PREPARE</strong><h3>Your operation</h3><p>Plan operator training, documentation and maintenance.</p></div></div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">ENGINEERING INSIGHTS</span><h2>Make a more informed decision.</h2></div></div>'''+guides()+'''</div></section>'''+cta()
page('/','Automatic Aluminium Anodizing Lines | Daimeng Technology','Explore Daimeng vertical and horizontal aluminium anodizing lines, intelligent controls and engineering solutions. Discuss your production requirements.',home)

# Additional routes are defined in pages.py to keep the content easy to maintain.
extra=ROOT/'src/pages.py'
if extra.exists(): exec(compile(extra.read_text(encoding='utf-8'),str(extra),'exec'))
for name in ['style.css','app.js']:
    src=ROOT/'src'/name
    if src.exists(): shutil.copy2(src,OUT/'assets'/name)
# Rewrite root-absolute links so they resolve under the publishing prefix (e.g. /daimeng-website/).
if PREFIX:
    rewritten=0
    for f in OUT.rglob('*.html'):
        t=f.read_text(encoding='utf-8')
        n=t.replace('href="/','href="'+PREFIX+'/').replace('src="/','src="'+PREFIX+'/')
        if n!=t:f.write_text(n,encoding='utf-8');rewritten+=1
    print(f'Applied prefix {PREFIX} to {rewritten} HTML files')
# GitHub Pages only looks for /404.html when a route is unknown; keep the /404/ page for other hosts.
if (OUT/'404/index.html').exists(): shutil.copy2(OUT/'404/index.html',OUT/'404.html')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p in PAGES)+'</urlset>',encoding='utf-8')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /api/\nSitemap: '+BASE+'/sitemap.xml\n',encoding='utf-8')
print(f'Built {len(PAGES)} pages in {OUT}')
